export default function Gallery({
  themeMode,
  onThemeMode,
}: {
  themeMode: ThemeMode;
  onThemeMode: (mode: ThemeMode) => void;
}) {
  const themes: readonly { id: ResolvedTheme; label: string }[] = [
    { id: "light", label: ja.gallery.themeLight },
    { id: "dark", label: ja.gallery.themeDark },
  ];

  // Open fixtures (menu popover) call scrollIntoView when Fluent autofocuses
  // the first item on mount; pin the gallery scroll to the top so the page
  // always opens at the light-theme section. The rAF covers any deferred
  // scroll scheduled after this effect runs.
  useEffect(() => {
    const pin = () => {
      const root = document.querySelector<HTMLElement>(".hs-gallery");
      if (root) root.scrollTop = 0;
      document.documentElement.scrollTop = 0;
      document.body.scrollTop = 0;
    };
    pin();
    const raf = requestAnimationFrame(pin);
    return () => cancelAnimationFrame(raf);
  }, []);

  return (
    <div className="hs-gallery" role="main" aria-label={ja.gallery.title}>
      <header className="hs-gallery__header">
        <h1 className="hs-gallery__title">{ja.gallery.title}</h1>
        <StatusBadge tone="info" label={ja.gallery.devBadge} />
        <span className="hs-gallery__spacer" />
        <SegmentedControl
          options={THEME_OPTIONS}
          value={themeMode}
          onChange={onThemeMode}
          ariaLabel={ja.settings.themeLabel}
        />
        <HsButton
          variant="subtle"
          onClick={() => {
            window.location.hash = "";
          }}
        >
          {ja.common.back}
        </HsButton>
        <p className="hs-gallery__note">{ja.gallery.note}</p>
      </header>

      {themes.map((t) => (
        <section key={t.id} data-hs-theme={t.id} className="hs-gallery__theme">
          <FluentProvider
            theme={t.id === "dark" ? hsDarkTheme : hsLightTheme}
            style={{ display: "contents" }}
          >
            <h2 className="hs-gallery__theme-title">{t.label}</h2>
            <PrimitiveSections />
          </FluentProvider>
        </section>
      ))}
    </div>
  );
}

/**
 * @vitest-environment jsdom
 *
 * #364 recent-projects UX: per-entry 履歴から削除 on the EMPTY list,
 * duplicate-name parent-dir sublines, and the projectOpenFailed card's
 * remove-and-close action. Exercises the real components through
 * ImportScreenBody with a fixture ImportView.
 */

import { act } from "react";
import { createRoot, type Root } from "react-dom/client";
import { afterEach, describe, expect, it, vi } from "vitest";
import { ImportScreenBody, type ImportView } from "./ImportStates";
import { DEFAULT_TRANSCRIPTION_OPTIONS } from "./types";
import { ja } from "../strings/ja";
import type { ScreenState } from "../workspace/screen";

(globalThis as Record<string, unknown>).IS_REACT_ACT_ENVIRONMENT = true;

let root: Root | null = null;
let host: HTMLDivElement | null = null;

const NOOP = () => undefined;

function view(overrides: Partial<ImportView>): ImportView {
  return {
    audio: null,
    openingLabel: null,
    openingKind: null,
    issue: null,
    sourceMissing: null,
    recentProjects: [],
    options: DEFAULT_TRANSCRIPTION_OPTIONS,
    onOpenAudio: NOOP,
    onOpenProject: NOOP,
    onRemoveRecent: NOOP,
    onPickRelink: NOOP,
    onDismissError: NOOP,
    onOptionsChange: NOOP,
    ...overrides,
  };
}

async function render(screen: ScreenState, v: ImportView): Promise<void> {
  host = document.createElement("div");
  document.body.appendChild(host);
  root = createRoot(host);
  await act(async () => {
    root!.render(<ImportScreenBody screen={screen} view={v} onTranscribe={NOOP} />);
  });
}

async function click(el: Element): Promise<void> {
  await act(async () => {
    (el as HTMLElement).click();
  });
}

afterEach(async () => {
  if (root) {
    await act(async () => {
      root!.unmount();
    });
  }
  root = null;
  host?.remove();
  host = null;
  document.body.innerHTML = "";
});

describe("EMPTY recents (#364)", () => {
  it("each row offers a keyboard-focusable 履歴から削除 button", async () => {
    const removed: string[] = [];
    await render(
      "empty",
      view({
        recentProjects: [
          { name: "etude", path: "C:\\a\\etude.hornscribe.json", openedAt: 2 },
          { name: "solo", path: "C:\\b\\solo.hornscribe.json", openedAt: 1 },
        ],
        onRemoveRecent: (p) => removed.push(p),
      }),
    );
    const removeButtons = [
      ...document.querySelectorAll<HTMLButtonElement>(".hs-recent__remove"),
    ];
    expect(removeButtons).toHaveLength(2);
    expect(removeButtons[0].getAttribute("aria-label")).toBe(
      ja.import.recent.removeAria("etude"),
    );
    await click(removeButtons[0]);
    expect(removed).toEqual(["C:\\a\\etude.hornscribe.json"]);
  });

  it("duplicate names get a parent-dir subline; unique names do not", async () => {
    await render(
      "empty",
      view({
        recentProjects: [
          { name: "etude", path: "C:\\one\\etude.hornscribe.json", openedAt: 3 },
          { name: "etude", path: "D:\\two\\etude.hornscribe.json", openedAt: 2 },
          { name: "solo", path: "C:\\b\\solo.hornscribe.json", openedAt: 1 },
        ],
      }),
    );
    const dirs = [...document.querySelectorAll(".hs-recent__dir")].map(
      (e) => e.textContent,
    );
    expect(dirs).toEqual(["C:\\one", "D:\\two"]);
  });
});

describe("projectOpenFailed card (#364)", () => {
  it("a failed MRU path offers remove-and-close plus pick-another", async () => {
    const removed: string[] = [];
    const dismissed = vi.fn();
    await render(
      "audioError",
      view({
        issue: {
          kind: "projectOpenFailed",
          fileName: "etude.hornscribe.json",
          path: "C:\\a\\etude.hornscribe.json",
        },
        onRemoveRecent: (p) => removed.push(p),
        onDismissError: dismissed,
      }),
    );
    const labels = [...document.querySelectorAll("button")].map(
      (b) => b.textContent,
    );
    expect(labels).toContain(ja.import.errors.chooseAnother);
    const removeBtn = [...document.querySelectorAll("button")].find(
      (b) => b.textContent === ja.import.errors.removeFromRecent,
    );
    expect(removeBtn).toBeTruthy();
    await click(removeBtn!);
    expect(removed).toEqual(["C:\\a\\etude.hornscribe.json"]);
    expect(dismissed).toHaveBeenCalledOnce();
  });

  it("a byte-open failure has no remove affordance (nothing in the MRU)", async () => {
    await render(
      "audioError",
      view({
        issue: { kind: "projectOpenFailed", fileName: "dropped.hornscribe.json" },
      }),
    );
    const labels = [...document.querySelectorAll("button")].map(
      (b) => b.textContent,
    );
    expect(labels).not.toContain(ja.import.errors.removeFromRecent);
    expect(labels).toContain(ja.import.errors.chooseAnother);
  });
});

/**
 * Import-owned score-region bodies (UI-020; docs/GUI_UX_SPEC.md §3/§4/§20).
 *
 * ScoreWorkspace delegates the import-side machine states here:
 *   empty         → drop headline + 開く CTA + formats + trust + recents
 *   openingAudio  → honest indeterminate progress (§5: no fake %)
 *   audioReady    → file metadata + 採譜を開始 + 採譜オプション popover
 *   audioError    → copy-deck error card (別のファイルを選ぶ / 閉じる)
 *   sourceMissing → 元音源が見つかりません card (音源を指定 / 閉じる)
 *
 * All copy resolves through ja.import / ja.emptyState / ja.score — the
 * copy deck (protocol/copy/ja-JP.json) is the source of truth.
 */
import {
  Dismiss16Regular,
  ErrorCircle24Regular,
  FolderOpen24Regular,
  History24Regular,
  Play24Regular,
  Mic24Regular,
  Speaker2Regular,
} from "@fluentui/react-icons";
import { Checkbox } from "@fluentui/react-components";
import { ja } from "../strings/ja";
